// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz the from address and the array length (encoded as a bytes blob to allow empty array fuzzing)
    // We use bytes for _tos encoding so the fuzzer can produce an empty array case.
    function testFuzz_property(address from, address someCounterparty, bytes memory tosEncoded, uint256 v) public {
        // Interpret tosEncoded as abi.encode(address[] memory _tos) to get an address[] with possibly zero length
        // Keep domain wide: no restrictive vm.assume; but ensure v is bounded reasonably to avoid huge gas use
        v = bound(v, 0, 1e9);

        // Decode tosEncoded to address[] if possible; if decoding fails, treat as empty array
        address[] memory _tos;
        if (tosEncoded.length == 0) {
            // produce an empty array
            _tos = new address[](0);
        } else {
            // attempt to decode; if it fails (malformed), fallback to empty
            try this.decodeAddressArray(tosEncoded) returns (address[] memory arr) {
                _tos = arr;
            } catch {
                _tos = new address[](0);
            }
        }

        // We will call c.transfer and observe whether it reverts. The reference contract MUST revert when _tos.length == 0.
        bool ok;
        try c.transfer(from, someCounterparty, _tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: whenever the provided _tos array is empty, the reference contract reverts (ok == false).
        // This will fail on the mutant because it removed the require and will return true for empty _tos.
        if (_tos.length == 0) {
            assertTrue(!ok);
        } else {
            // for non-empty arrays, both versions may or may not revert depending on external calls; we make no assertion
            assertTrue(true);
        }
    }

    // helper to decode bytes -> address[] using external call so try/catch works consistently
    function decodeAddressArray(bytes memory b) external pure returns (address[] memory) {
        return abi.decode(b, (address[]));
    }
}
